use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::state_rw;
use crate::wasi::clocks::wall_clock;

struct Node;

// NOTE: The node's `with` clause lists three grants (http-client, notifier,
// wall-clock). This body also imports `aap:caps/state-rw@0.1.0`, which was
// approved as an extension. The `with` clause and any manifest derived from it
// should be updated to include state-rw so the declared authority matches the
// imports actually present in the world.

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input this call received under the shared key `last-input`.
        state_rw::put("last-input", &feed_url);

        let now = wall_clock::now();

        // A transport failure is a value; count it as nothing fetched.
        // An out-of-allowlist request traps at the boundary, as specified.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat seconds={} fetched={}", now.seconds, fetched);
        let notified = notifier::notify(&message);

        // The `ensures notified == true` contract must hold of every output.
        // Trap rather than return a report that claims otherwise.
        assert!(notified, "notifier did not accept the heartbeat");

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
